      await widget.manager.signInWithProvider(provider);
      if (mounted) Navigator.of(context).pop();
    } on FaNetworkException catch (e) {
      _fail(e.message);
    } on AuthFlowException catch (e) {
      _fail(e.message);
    } on Object catch (e) {
      _fail('$e');
    }
  }

