    try {
      await widget.manager.signIn(login: login, password: [REDACTED:Sensitive Value]);
      if (mounted) Navigator.of(context).pop();
    } on FaNetworkException catch (e) {
      _fail(e.message, dev: true);
    } on Object catch (e) {
      _fail('$e', dev: true);
    }
  }

  void _fail(String message, {bool dev = false}) {
    if (!mounted) return;
    setState(() {
      _error = message;
      if (dev) {
